## 🧩 `GearRenderer.cs`

This script assembles a modular gear prefab from components and applies rarity/affix visuals.

```csharp
using UnityEngine;
using System.Collections.Generic;

public class GearRenderer : MonoBehaviour
{
    [System.Serializable]
    public class GearComponentSlot {
        public string slotName;           // e.g. "blade"
        public Transform anchor;          // Where the sprite goes
        public SpriteRenderer renderer;   // The SpriteRenderer to assign
    }

    public List<GearComponentSlot> componentSlots = new();

    [Header("Rarity Effects")]
    public SpriteRenderer rarityGlow;
    public Material[] rarityMaterials; // indexed by rarity enum (0=Common, 1=Uncommon...)

    [Header("Affix VFX Anchors")]
    public Transform vfxRoot;
    public List<AffixEffectLibrary> affixEffectPrefabs;

    public void RenderGear(ItemData item)
    {
        // Clear existing VFX
        foreach (Transform child in vfxRoot) Destroy(child.gameObject);

        // Apply component sprites
        foreach (var comp in item.components)
        {
            var slot = componentSlots.Find(s => s.slotName == comp.slot);
            if (slot != null)
            {
                Sprite sprite = Resources.Load<Sprite>($"Sprites/Gear/{comp.slot}/{comp.id}");
                slot.renderer.sprite = sprite;
            }
        }

        // Apply rarity material
        if (rarityGlow != null && (int)item.rarity < rarityMaterials.Length)
        {
            rarityGlow.material = rarityMaterials[(int)item.rarity];
        }

        // Add affix VFX
        foreach (var affix in item.affixes)
        {
            var vfx = affixEffectPrefabs.Find(a => a.affixId == affix);
            if (vfx != null)
            {
                Instantiate(vfx.vfxPrefab, vfxRoot);
            }
        }
    }
}
```

