# 1️⃣ StatusVisuals.cs  
**(Central style + emoji + color registry)**

```csharp
using System.Collections.Generic;
using UnityEngine;

public static class StatusVisuals
{
    public struct Visual
    {
        public string Emoji;
        public string Label;
        public Color Color;
        public float PulseSpeed;
        public float PulseScale;
    }

    private static readonly Dictionary<string, Visual> Map = new()
    {
        ["burning"]  = new Visual { Emoji = "🔥", Label = "Burning",  Color = new Color(1f, 0.35f, 0.1f), PulseSpeed = 7f, PulseScale = 0.14f },
        ["poisoned"] = new Visual { Emoji = "☠️", Label = "Poisoned", Color = new Color(0.2f, 1f, 0.35f), PulseSpeed = 6f, PulseScale = 0.12f },
        ["slowed"]   = new Visual { Emoji = "❄️", Label = "Slowed",   Color = new Color(0.4f, 0.85f, 1f), PulseSpeed = 4f, PulseScale = 0.10f },
        ["blessed"]  = new Visual { Emoji = "✨", Label = "Blessed",  Color = new Color(1f, 0.95f, 0.6f), PulseSpeed = 3f, PulseScale = 0.08f },
        ["cursed"]   = new Visual { Emoji = "🕷️", Label = "Cursed",   Color = new Color(0.85f, 0.25f, 1f), PulseSpeed = 8f, PulseScale = 0.15f },
        ["shocked"]  = new Visual { Emoji = "⚡", Label = "Shocked",  Color = new Color(1f, 0.95f, 0.3f), PulseSpeed = 10f, PulseScale = 0.18f }
    };

    public static Visual Get(string id)
    {
        id = id?.ToLowerInvariant();
        return Map.TryGetValue(id, out var v)
            ? v
            : new Visual { Emoji = "✦", Label = id ?? "Status", Color = Color.white, PulseSpeed = 5f, PulseScale = 0.1f };
    }
}
