# 2️⃣ FloatingCombatText.cs  
**(Big juicy numbers that POP, wobble, and fade)**

```csharp
using UnityEngine;
using UnityEngine.UI;

public class FloatingCombatText : MonoBehaviour
{
    public Text text;
    public float lifetime = 0.9f;
    public float riseSpeed = 90f;
    public float popScale = 1.5f;

    float t;
    Vector2 drift;

    void Awake()
    {
        text ??= GetComponent<Text>();
        drift = Random.insideUnitCircle * 25f;
        transform.localScale = Vector3.one;
    }

    void Update()
    {
        t += Time.deltaTime;
        float u = t / lifetime;

        transform.localPosition += new Vector3(drift.x, riseSpeed, 0) * Time.deltaTime;
        transform.localScale = Vector3.one * Mathf.Lerp(popScale, 1f, u);

        var c = text.color;
        c.a = Mathf.Lerp(1f, 0f, u);
        text.color = c;

        if (t >= lifetime) Destroy(gameObject);
    }
}
```

