# 3️⃣ StatusOverlayController.cs  
**(The star of the show — builds world‑space UI automatically)**

```csharp
using UnityEngine;
using UnityEngine.UI;
using System.Collections.Generic;

public class StatusOverlayController : MonoBehaviour
{
    public Vector3 offset = new(0, 1.2f, 0);
    public float uiScale = 0.01f;

    Canvas canvas;
    RectTransform statusRoot;
    RectTransform damageRoot;

    Dictionary<string, Text> statusTexts = new();

    void Awake()
    {
        BuildUI();
    }

    void LateUpdate()
    {
        canvas.transform.position = transform.position + offset;
        if (Camera.main)
            canvas.transform.rotation = Camera.main.transform.rotation;
    }

    void BuildUI()
    {
        canvas = new GameObject("StatusOverlay").AddComponent<Canvas>();
        canvas.renderMode = RenderMode.WorldSpace;
        canvas.sortingOrder = 999;
        canvas.transform.SetParent(transform, false);

        var rt = canvas.GetComponent<RectTransform>();
        rt.sizeDelta = new Vector2(400, 300);
        rt.localScale = Vector3.one * uiScale;

        statusRoot = CreateRoot("Statuses", new Vector2(0, 40));
        damageRoot = CreateRoot("Damage", new Vector2(0, -20));
    }

    RectTransform CreateRoot(string name, Vector2 pos)
    {
        var go = new GameObject(name);
        go.transform.SetParent(canvas.transform, false);
        var rt = go.AddComponent<RectTransform>();
        rt.anchoredPosition = pos;
        rt.sizeDelta = new Vector2(400, 200);

        var layout = go.AddComponent<VerticalLayoutGroup>();
        layout.childAlignment = TextAnchor.UpperCenter;
        layout.spacing = 2;

        return rt;
    }

    public void SetStatus(string id, int stacks)
    {
        if (stacks <= 0) { RemoveStatus(id); return; }

        if (!statusTexts.TryGetValue(id, out var txt))
        {
            txt = CreateText(statusRoot, 22);
            statusTexts[id] = txt;
        }

        var v = StatusVisuals.Get(id);
        txt.text = $"{v.Emoji} {v.Label} x{stacks}";
        txt.color = v.Color;
        txt.transform.localScale =
            Vector3.one * (1f + Mathf.Sin(Time.time * v.PulseSpeed) * v.PulseScale);
    }

    public void RemoveStatus(string id)
    {
        if (statusTexts.TryGetValue(id, out var txt))
        {
            Destroy(txt.gameObject);
            statusTexts.Remove(id);
        }
    }

    public void SpawnDamage(float amount, string element, bool crit, bool dot)
    {
        var txt = CreateText(damageRoot, crit ? 30 : 26);
        txt.text = (crit ? "💥 " : "") + Mathf.RoundToInt(amount).ToString();

        txt.color = element switch
        {
            "fire" => new Color(1f, 0.45f, 0.15f),
            "poison" => new Color(0.2f, 1f, 0.35f),
            "ice" => new Color(0.35f, 0.85f, 1f),
            "holy" => new Color(1f, 0.95f, 0.6f),
            _ => Color.white
        };

        txt.gameObject.AddComponent<FloatingCombatText>();
    }

    Text CreateText(RectTransform parent, int size)
    {
        var go = new GameObject("Text");
        go.transform.SetParent(parent, false);
        var t = go.AddComponent<Text>();
        t.font = Resources.GetBuiltinResource<Font>("Arial.ttf");
        t.fontSize = size;
        t.alignment = TextAnchor.MiddleCenter;
        t.horizontalOverflow = HorizontalWrapMode.Overflow;
        t.verticalOverflow = VerticalWrapMode.Overflow;
        go.AddComponent<Outline>();
        return t;
    }
}
```

